1	// Red-first fixtures for this pack's checks: each check is exercised against a
2	// violating input (it must fire) and a clean one (it must stay quiet), plus the
3	// staleness case where the guard can no longer find what it guards.
4	//
5	// Run with the Node test runner — no dependency, no install:
6	//   node --test .claudinite/local/packs/shouts-and-whispers/pack.test.mjs
7	//
8	// The last case in each block runs the check against the REAL repo tree, so a
9	// check that has silently stopped matching the project's actual files fails here
10	// rather than passing vacuously in CI.
11	import { test } from 'node:test';
12	import assert from 'node:assert/strict';
13	import { readFileSync } from 'node:fs';
14	import { join, dirname } from 'node:path';
15	import { fileURLToPath } from 'node:url';
16	import { execFileSync } from 'node:child_process';
17	
18	import crossTierConstants from './cross-tier-constants.mjs';
19	import geohashPrecisionParity from './geohash-precision-parity.mjs';
20	import geohashVectorParity from './geohash-vector-parity.mjs';
21	
22	const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..', '..');
23	
24	// A minimal stand-in for the engine's check context: the two accessors these
25	// dependency-free checks use.
26	const ctxOf = (files) => ({
27	  files: Object.keys(files),
28	  read: (p) => (p in files ? files[p] : null),
29	});
30	
31	// The real tree, as the engine would present it.
32	const realCtx = () => ({
33	  files: execFileSync('git', ['ls-files'], { cwd: repoRoot, encoding: 'utf8' })
34	    .split('\n').filter(Boolean),
35	  read(p) {
36	    try { return readFileSync(join(repoRoot, p), 'utf8'); } catch { return null; }
37	  },
38	});
39	
40	const CONSTANTS_TS = (whisper) => `
41	export const WHISPER_RADIUS_M = ${whisper};
42	export const SHOUT_RADIUS_M = 1500;
43	export const MAX_TEXT_LEN = 500;
44	export const REGION = 'us-central1';
45	`;
46	
47	const CONFIG_DART = `
48	const int whisperRadiusM = 150;
49	const int shoutRadiusM = 1500;
50	const int maxTextLen = 500;
51	const String functionsRegion = 'us-central1';
52	`;
53	
54	const DESIGN_MD = `
55	## 10. Constants (single source of truth)
56	
57	| constant          | value  | lives in |
58	|-------------------|--------|----------|
59	| \`WHISPER_RADIUS_M\`| 150    | both     |
60	| \`SHOUT_RADIUS_M\`  | 1500   | both     |
61	| \`MAX_TEXT_LEN\`    | 500    | both     |
62	`;
63	
64	const constantsFiles = (whisper) => ({
65	  'firebase/functions/src/constants.ts': CONSTANTS_TS(whisper),
66	  'app/lib/config.dart': CONFIG_DART,
67	  'docs/DESIGN.md': DESIGN_MD,
68	});
69	
70	test('cross-tier-constants: fires when the server radius drifts from the client', () => {
71	  const findings = crossTierConstants.run(ctxOf(constantsFiles(200)));
72	  assert.equal(findings.length, 1);
73	  assert.match(findings[0].what, /whisperRadiusM is 150 but .* is 200/);
74	  assert.equal(findings[0].severity, 'blocking');
75	});
76	
77	test('cross-tier-constants: fires when both tiers agree but §10 does not', () => {
78	  const files = constantsFiles(150);
79	  files['docs/DESIGN.md'] = DESIGN_MD.replace('| 150 ', '| 250 ');
80	  const findings = crossTierConstants.run(ctxOf(files));
81	  assert.equal(findings.length, 1);
82	  assert.equal(findings[0].file, 'docs/DESIGN.md');
83	  assert.match(findings[0].what, /documents WHISPER_RADIUS_M as 250/);
84	});
85	
86	test('cross-tier-constants: quiet when every pair agrees', () => {
87	  assert.deepEqual(crossTierConstants.run(ctxOf(constantsFiles(150))), []);
88	});
89	
90	test('cross-tier-constants: fires when a guarded constant is renamed away', () => {
91	  const files = constantsFiles(150);
92	  files['app/lib/config.dart'] = CONFIG_DART.replace('maxTextLen', 'maxMessageLen');
93	  const findings = crossTierConstants.run(ctxOf(files));
94	  assert.equal(findings.length, 1);
95	  assert.match(findings[0].what, /no longer finds maxTextLen/);
96	});
97	
98	test('cross-tier-constants: quiet on the real repo', () => {
99	  assert.deepEqual(crossTierConstants.run(realCtx()), []);
100	});
101	
102	const geohashFiles = (clientPrecision, serverPrecision) => ({
103	  'app/lib/adapters/geolocator_location_adapter.dart':
104	    `'geohash': geohash.encode(p.lat, p.lng, precision: ${clientPrecision}),`,
105	  'firebase/functions/src/index.ts':
106	    `const geohash = geohashForLocation([lat, lng], ${serverPrecision});`,
107	});
108	
109	test('geohash-precision-parity: fires when the tiers encode at different precisions', () => {
110	  const findings = geohashPrecisionParity.run(ctxOf(geohashFiles(9, 10)));
111	  assert.equal(findings.length, 1);
112	  assert.match(findings[0].what, /precision disagrees across the tiers/);
113	  assert.equal(findings[0].file, 'firebase/functions/src/index.ts');
114	  assert.equal(findings[0].line, 1);
115	});
116	
117	test('geohash-precision-parity: quiet when both tiers encode at 9', () => {
118	  assert.deepEqual(geohashPrecisionParity.run(ctxOf(geohashFiles(9, 9))), []);
119	});
120	
121	test('geohash-precision-parity: fires when a call site drops the explicit precision', () => {
122	  const files = geohashFiles(9, 9);
123	  files['firebase/functions/src/index.ts'] =
124	    'const geohash = geohashForLocation([lat, lng]);';
125	  const findings = geohashPrecisionParity.run(ctxOf(files));
126	  assert.equal(findings.length, 1);
127	  assert.match(findings[0].what, /no explicit geohash precision found/);
128	});
129	
130	test('geohash-precision-parity: quiet on the real repo', () => {
131	  assert.deepEqual(geohashPrecisionParity.run(realCtx()), []);
132	});
133	
134	// The paired known-vector suites. Each fixture carries the deliberately
135	// UNPAIRED assertions too — the client's explicit-precision cases and the
136	// server's default-precision (10-char) ones — so the fixtures prove the guard
137	// reads only the shared precision-9 vectors and not every geohash literal in
138	// sight.
139	const GEOHASH_DART = (extra = '') => `
140	test('canonical Wikipedia vector', () {
141	  expect(encode(57.64911, 10.40744), 'u4pruydqq');
142	  expect(encode(57.64911, 10.40744, precision: 11), 'u4pruydqqvj');
